func main() {
	products := []Product{
		{Name: "Ноутбук", Price: 80000, Rating: 4.8},
		{Name: "Мышь", Price: 1500, Rating: 4.5},
		{Name: "Клавиатура", Price: 4500, Rating: 4.8},
		{Name: "Монитор", Price: 25000, Rating: 4.2},
	}

